      "label": "A",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "睡醒睁开双眼的时候"
        },
        {
          "id": "V1-02",
          "zh": "翻开书页之上独自一人"
        },
        {
          "id": "V1-03",
          "zh": "四处张望却看不见"
        },
        {
          "id": "V1-04",
          "zh": "没有方向没有出口"
        },
        {
          "id": "V1-05",
          "zh": "然后我听见的是"
        },
        {
          "id": "V1-06",
          "zh": "呼唤着我名字的你的声音"
        },
        {
          "id": "V1-07",
          "zh": "摸索着说出的言语"
        },
        {
          "id": "V1-08",
          "zh": "迈步向前走"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "从睡梦里睁开眼"
        },
        {
          "id": "V1-02",
          "zh": "摊开的书页上 只剩我一人"
        },
        {
          "id": "V1-03",
          "zh": "环顾四周 不见"
        },
        {
          "id": "V1-04",
          "zh": "方向 也没有出口"
        },
        {
          "id": "V1-05",
          "zh": "然后我听见了"
        },
        {
          "id": "V1-06",
          "zh": "那呼唤我名字的 你的声音"
        },
        {
          "id": "V1-07",
          "zh": "凭着摸索的话语"
        },
        {
          "id": "V1-08",
          "zh": "迈出了脚步"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "从梦里睁开双眼的时候"
        },
        {
          "id": "V1-02",
          "zh": "我站在翻开的一页白纸上 一个人"
        },
        {
          "id": "V1-03",
          "zh": "转一圈 什么都看不见"
        },
        {
          "id": "V1-04",
          "zh": "没有门 也没有路"
        },
        {
          "id": "V1-05",
          "zh": "空白里 有声音传过来"
        },
        {
          "id": "V1-06",
          "zh": "是你轻轻喊我名字 尾音微微发抖"
        },
        {
          "id": "V1-07",
          "zh": "摸索着 说出第一句话"
        },
        {
          "id": "V1-08",
          "zh": "迈出这第一步"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "从睡梦中睁开双眼"
        },
        {
          "id": "V1-02",
          "zh": "在摊开的书页上独自一人"
        },
        {
          "id": "V1-03",
          "zh": "四处张望却看不见"
        },
        {
          "id": "V1-04",
          "zh": "目标和出口都没有"
        },
        {
          "id": "V1-05",
          "zh": "然后我听见的是"
        },
        {
          "id": "V1-06",
          "zh": "呼唤我名字的你的声音"
        },
        {
          "id": "V1-07",
          "zh": "摸索着的话语和"
        },
        {
          "id": "V1-08",
          "zh": "开始迈出的脚步"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "从漫长的梦里睁开眼睛"
        },
        {
          "id": "V1-02",
          "zh": "我一个人站在翻开的空白页中央"
        },
        {
          "id": "V1-03",
          "zh": "转过身 四面都看不见"
        },
        {
          "id": "V1-04",
          "zh": "没有门也没有路"
        },
        {
          "id": "V1-05",
          "zh": "耳朵里 忽然落进一声"
        },
        {
          "id": "V1-06",
          "zh": "是你在叫我的名字 轻轻地 一声声"
        },
        {
          "id": "V1-07",
          "zh": "摸黑捡起散落的词语"
        },
        {
          "id": "V1-08",
          "zh": "开始迈出脚步"
        }
      ]
    }
  ]
}

